<?php
declare(strict_types=1);namespace Haerriz\AgenticCommerce\Model\Resolver;
use Haerriz\AgenticCommerce\Model\Cart\CartService;use Haerriz\AgenticCommerce\Model\GraphQl\CustomerContext;use Haerriz\AgenticCommerce\Model\GraphQl\IdempotentExecutor;use Magento\Framework\Exception\{AuthorizationException,LocalizedException};use Magento\Framework\GraphQl\Config\Element\Field;use Magento\Framework\GraphQl\Exception\{GraphQlAuthorizationException,GraphQlInputException};use Magento\Framework\GraphQl\Query\ResolverInterface;use Magento\Framework\GraphQl\Schema\Type\ResolveInfo;
class RemoveFromCartResolver implements ResolverInterface{public function __construct(private CartService $cartService,private CustomerContext $customerContext,private IdempotentExecutor $idempotency){}public function resolve(Field $field,$context,ResolveInfo $info,array $value=null,array $args=null){$i=(array)($args['input']??[]);if(empty($i['item_id'])&&empty($i['sku']))throw new GraphQlInputException(__('item_id or sku is required.'));$identity=$this->customerContext->identityForTool($context,$i['client_id']??null,'remove_cart_item');try{return$this->idempotency->execute('remove_cart_item',$i,$identity,fn():array=>$this->cartService->removeItem($identity,!empty($i['item_id'])?(int)$i['item_id']:null,!empty($i['sku'])?(string)$i['sku']:null,isset($i['cart_id'])?(string)$i['cart_id']:null));}catch(AuthorizationException $e){throw new GraphQlAuthorizationException(__($e->getMessage()));}catch(LocalizedException $e){throw new GraphQlInputException(__($e->getMessage()));}}}
